-- Tests both production grants and RLS independently. All temporary grants roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
-- Populate both child tables before denial assertions so empty results prove filtering.
insert into public.assets(story_id,kind,storage_path,mime_type) values
 ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/ffffffff-ffff-4fff-8fff-ffffffffffff.png','image/png'),
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','hero','22222222-2222-4222-8222-222222222222/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1/ffffffff-ffff-4fff-8fff-fffffffffff2.png','image/png');
insert into public.story_pages(story_id,page_number,content) values
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',1,'Synthetic page owned by Bob through its parent.');
select is((select count(*) from public.assets),2::bigint,'Assets exist before role tests');
select is((select count(*) from public.story_pages),4::bigint,'Pages exist for both owners before role tests');
select ok(not has_table_privilege('anon', 'public.stories', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'anon has no grants on stories');
select ok(not has_table_privilege('anon', 'public.story_pages', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'anon has no grants on story_pages');
select ok(not has_table_privilege('anon', 'public.assets', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'anon has no grants on assets');
select ok(not has_table_privilege('authenticated', 'public.stories', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'authenticated has no grants on stories');
select ok(not has_table_privilege('authenticated', 'public.story_pages', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'authenticated has no grants on story_pages');
select ok(not has_table_privilege('authenticated', 'public.assets', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'authenticated has no grants on assets');
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select throws_ok($$select * from public.stories$$,'42501',null,'anonymous: grants protect stories read');
select throws_ok($$update public.stories set id=id$$,'42501',null,'anonymous: grants protect stories update');
select throws_ok($$delete from public.stories$$,'42501',null,'anonymous: grants protect stories delete');
select throws_ok($$insert into public.stories(owner_id,title,child_name,prompt) values ('11111111-1111-4111-8111-111111111111','Test','Nova','A map')$$,'42501',null,'anonymous: grants protect stories inserts');
select throws_ok($$select * from public.story_pages$$,'42501',null,'anonymous: grants protect story_pages read');
select throws_ok($$update public.story_pages set id=id$$,'42501',null,'anonymous: grants protect story_pages update');
select throws_ok($$delete from public.story_pages$$,'42501',null,'anonymous: grants protect story_pages delete');
select throws_ok($$insert into public.story_pages(story_id,page_number,content) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',4,'Test')$$,'42501',null,'anonymous: grants protect story_pages inserts');
select throws_ok($$select * from public.assets$$,'42501',null,'anonymous: grants protect assets read');
select throws_ok($$update public.assets set id=id$$,'42501',null,'anonymous: grants protect assets update');
select throws_ok($$delete from public.assets$$,'42501',null,'anonymous: grants protect assets delete');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/dddddddd-dddd-4ddd-8ddd-dddddddddddd.png','image/png')$$,'42501',null,'anonymous: grants protect assets inserts');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select is(auth.uid(), '11111111-1111-4111-8111-111111111111'::uuid, 'Alice identity is set correctly');
select throws_ok($$select * from public.stories$$,'42501',null,'Alice: grants protect stories read');
select throws_ok($$update public.stories set id=id$$,'42501',null,'Alice: grants protect stories update');
select throws_ok($$delete from public.stories$$,'42501',null,'Alice: grants protect stories delete');
select throws_ok($$insert into public.stories(owner_id,title,child_name,prompt) values ('11111111-1111-4111-8111-111111111111','Test','Nova','A map')$$,'42501',null,'Alice: grants protect stories inserts');
select throws_ok($$select * from public.story_pages$$,'42501',null,'Alice: grants protect story_pages read');
select throws_ok($$update public.story_pages set id=id$$,'42501',null,'Alice: grants protect story_pages update');
