select throws_ok($$update public.stories set id=id$$,'42501',null,'Bob: grants protect stories update');
select throws_ok($$delete from public.stories$$,'42501',null,'Bob: grants protect stories delete');
select throws_ok($$insert into public.stories(owner_id,title,child_name,prompt) values ('11111111-1111-4111-8111-111111111111','Test','Nova','A map')$$,'42501',null,'Bob: grants protect stories inserts');
select throws_ok($$select * from public.story_pages$$,'42501',null,'Bob: grants protect story_pages read');
select throws_ok($$update public.story_pages set id=id$$,'42501',null,'Bob: grants protect story_pages update');
select throws_ok($$delete from public.story_pages$$,'42501',null,'Bob: grants protect story_pages delete');
select throws_ok($$insert into public.story_pages(story_id,page_number,content) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',4,'Test')$$,'42501',null,'Bob: grants protect story_pages inserts');
select throws_ok($$select * from public.assets$$,'42501',null,'Bob: grants protect assets read');
select throws_ok($$update public.assets set id=id$$,'42501',null,'Bob: grants protect assets update');
select throws_ok($$delete from public.assets$$,'42501',null,'Bob: grants protect assets delete');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/dddddddd-dddd-4ddd-8ddd-dddddddddddd.png','image/png')$$,'42501',null,'Bob: grants protect assets inserts');
reset role;
grant select,insert,update,delete on public.stories,public.story_pages,public.assets to anon,authenticated;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*) from public.stories),0::bigint,'anonymous: RLS protect stories reads');
select results_eq($$update public.stories set id=id returning id$$,array[]::uuid[],'anonymous: RLS protect stories updates');
select results_eq($$delete from public.stories returning id$$,array[]::uuid[],'anonymous: RLS protect stories deletes');
