select is((select count(*) from public.assets),0::bigint,'anonymous: RLS protect assets reads');
select results_eq($$update public.assets set id=id returning id$$,array[]::uuid[],'anonymous: RLS protect assets updates');
select results_eq($$delete from public.assets returning id$$,array[]::uuid[],'anonymous: RLS protect assets deletes');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/dddddddd-dddd-4ddd-8ddd-dddddddddddd.png','image/png')$$,'42501',null,'anonymous: RLS protect assets inserts');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select is(auth.uid(), '11111111-1111-4111-8111-111111111111'::uuid, 'Alice identity is set correctly');
select is((select count(*) from public.stories),0::bigint,'Alice: RLS protect stories reads');
select results_eq($$update public.stories set id=id returning id$$,array[]::uuid[],'Alice: RLS protect stories updates');
select results_eq($$delete from public.stories returning id$$,array[]::uuid[],'Alice: RLS protect stories deletes');
