select is((select count(*) from public.story_pages),0::bigint,'Alice: RLS protect story_pages reads');
select results_eq($$update public.story_pages set id=id returning id$$,array[]::uuid[],'Alice: RLS protect story_pages updates');
select results_eq($$delete from public.story_pages returning id$$,array[]::uuid[],'Alice: RLS protect story_pages deletes');
select throws_ok($$insert into public.story_pages(story_id,page_number,content) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',4,'Test')$$,'42501',null,'Alice: RLS protect story_pages inserts');
select is((select count(*) from public.assets),0::bigint,'Alice: RLS protect assets reads');
select results_eq($$update public.assets set id=id returning id$$,array[]::uuid[],'Alice: RLS protect assets updates');
select results_eq($$delete from public.assets returning id$$,array[]::uuid[],'Alice: RLS protect assets deletes');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/dddddddd-dddd-4ddd-8ddd-dddddddddddd.png','image/png')$$,'42501',null,'Alice: RLS protect assets inserts');
