select is((select count(*) from public.stories),0::bigint,'Bob: RLS protect stories reads');
select results_eq($$update public.stories set id=id returning id$$,array[]::uuid[],'Bob: RLS protect stories updates');
select results_eq($$delete from public.stories returning id$$,array[]::uuid[],'Bob: RLS protect stories deletes');
select throws_ok($$insert into public.stories(owner_id,title,child_name,prompt) values ('11111111-1111-4111-8111-111111111111','Test','Nova','A map')$$,'42501',null,'Bob: RLS protect stories inserts');
select is((select count(*) from public.story_pages),0::bigint,'Bob: RLS protect story_pages reads');
select results_eq($$update public.story_pages set id=id returning id$$,array[]::uuid[],'Bob: RLS protect story_pages updates');
